```typescript
const buildNestedState = (routes: string[], currentIndex: number): RouteNode => {
    if (currentIndex >= routes.length) {
        throw new Error(`Invalid route index ${currentIndex} for routes array of length ${routes.length}`);
    }

    const currentRoute = routes[currentIndex];

    if (!currentRoute) {
        throw new Error(`Route at index ${currentIndex} is undefined or empty`);
    }

    // If this is the last route, create leaf node with path
    if (currentIndex === routes.length - 1) {
        return {
            name: currentRoute,
            path,
        };
    }

    // Create intermediate node with nested state
    return {
        name: currentRoute,
        state: {
            routes: [buildNestedState(routes, currentIndex + 1)],
            index: 0,
        },
    };
};
```

